package com.example.apphear.sentenceassist

/**
 * English forms allowed for each recognizer gloss (`assets/sentence_assist/lexicon_v2.json`,
 * generated by `tools/sentence_assist/build_lexicon.py`). Forms are stored pre-tokenized so
 * multi-word forms ("do not know") match token sequences.
 */
class GlossLexicon(
    glossForms: Map<String, List<String>>,
    grammarWords: Collection<String>,
    inferablePronouns: Collection<String>,
) {
    val glosses: Set<String> = glossForms.keys
    val grammarWords: Set<String> = grammarWords.toSet()
    val inferablePronouns: Set<String> = inferablePronouns.toSet()
    private val forms: Map<String, List<List<String>>> = glossForms.mapValues { (_, values) ->
        values.map(SentenceTokenizer::tokens).filter { it.isNotEmpty() }.distinct()
    }

    init {
        require(forms.isNotEmpty()) { "Empty lexicon" }
        require(forms.values.all { it.isNotEmpty() }) { "Every gloss needs at least one form" }
        require(this.inferablePronouns.none { it in this.grammarWords }) { "Pronouns overlap grammar" }
    }

    fun formsOf(gloss: String): List<List<String>> = forms[gloss].orEmpty()

    /** Citation English for a gloss: its label without the variant number when that is a form
     * ("HOW1" -> "how"), else its first listed form ("DONTKNOW" -> "do not know"). */
    fun displayForm(gloss: String): String {
        val candidates = formsOf(gloss)
        val base = gloss.lowercase(java.util.Locale.US).trimEnd { it.isDigit() }
        return (candidates.firstOrNull { it == listOf(base) } ?: candidates.firstOrNull())
            ?.joinToString(" ") ?: base
    }

    /** The vocabulary a lexicon was built for must be exactly the recognizer's label set. */
    fun coversExactly(vocabulary: Collection<String>): Boolean = glosses == vocabulary.toSet()

    companion object {
        const val SCHEMA_VERSION = 1
    }
}
